TLM.f("Tempora/Quad2-1",{"officium":"Feria Secunda infra Hebdomadam II in Quadragesima","rule":["no Gloria","Suffragium=Sanctorum;Vivis;;","Super popul"],"ruleInherited":["no Gloria","Credo","Prefatio=Quad","Suffragium=Sanctorum;Vivis;;"],"fallback":"Tempora/Quad2-0","sections":{"Introitus":[{"k":"ref","la":"Ps 25:11-12"},{"k":"text","la":"Rédime me, Dómine, et miserére mei: pes enim meus stetit in via recta: in ecclésiis benedícam Dóminum."},{"k":"ref","la":"Ps 25:1"},{"k":"text","la":"Júdica me, Dómine, quóniam ego in innocéntia mea ingréssus sum: et in Dómino sperans, non infirmábor."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Rédime me, Dómine, et miserére mei: pes enim meus stetit in via recta: in ecclésiis benedícam Dóminum."}],"Oratio":[{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut família tua, quæ se, affligéndo carnem, ab aliméntis ábstinet: sectándo justítiam, a culpa jejúnet."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Daniélis Prophétæ."},{"k":"ref","la":"Dan 9:15-19"},{"k":"text","la":"In diébus illis: Orávit Dániel Dóminum, dicens: Dómine, Deus noster, qui eduxísti pópulum tuum de terra Ægýpti in manu forti, et fecísti tibi nomen secúndum diem hanc; peccávimus, iniquitátem fécimus, Dómine, in omnem justítiam tuam: avertátur, óbsecro, ira tua et furor tuus a civitáte tua Jerúsalem et monte sancto tuo. Propter peccáta enim nostra et iniquitátes patrum nostrórum. Jerúsalem et pópulus tuus in oppróbrium sunt ómnibus per circúitum nostrum. Nunc ergo exáudi, Deus noster, oratiónem servi tui et preces ejus: et osténde fáciem tuam super sanctuárium tuum, quod desértum est, propter temetípsum. Inclína, Deus meus, aurem tuam, et audi: áperi óculos tuos, et vide desolatiónem nostram et civitátem, super quam invocátum est nomen tuum: neque enim in justificatiónibus nostris prostérnimus preces ante fáciem tuam, sed in miseratiónibus tuis multis. Exáudi, Dómine, placáre, Dómine: atténde et fac: ne moréris propter temetípsum, Deus meus: quia nomen tuum invocátum est super civitátem et super pópulum tuum, Dómine, Deus noster."}],"Graduale":[{"k":"ref","la":"Ps 69:6; 69:3"},{"k":"text","la":"Adjútor meus et liberátor meus esto: Dómine, ne tardáveris."},{"k":"text","la":"Confundántur et revereántur inimíci mei, qui quærunt ánimam meam.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 102:10"},{"k":"text","la":"Dómine, non secúndum peccáta nostra, quæ fécimus nos: neque secúndum iniquitátes nostras retríbuas nobis"},{"k":"ref","la":"Ps 78:8-9"},{"k":"text","la":"Dómine, ne memíneris iniquitátum nostrárum antiquárum: cito antícipent nos misericórdiæ tuæ, quia páuperes facti sumus nimis. (Hic genuflectitur)"},{"k":"text","la":"Adjuva nos, Deus, salutáris noster: et propter glóriam nóminis tui, Dómine, líbera nos: et propítius esto peccátis nostris, propter nomen tuum.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem."},{"k":"ref","la":"Joh 8:21-29"},{"k":"text","la":"In illo témpore: Dixit Jesus turbis Judæórum: Ego vado, et quærétis me, et in peccáto vestro moriémini. Quo ego vado, vos non potéstis veníre. Dicébant ergo Judǽi: Numquid interfíciet semetípsum, quia dixit: Quo ego vado, vos non potéstis veníre? Et dicébat eis: Vos de deórsum estis, ego de supérnis sum. Vos de mundo hoc estis, ego non sum de hoc mundo. Dixi ergo vobis, quia moriémini in peccátis vestris: si enim non credidéritis, quia ego sum, moriémini in peccáto vestro. Dicébant ergo ei: Tu quis es? Dixit eis Jesus: Princípium, qui et loquor vobis. Multa habeo de vobis loqui et judicáre. Sed qui me misit, verax est: et ego quæ audívi ab eo, hæc loquor in mundo. Et non cognovérunt, quia Patrem ejus dicébat Deum. Dixit ergo eis Jesus: Cum exaltavéritis Fílium hóminis, tunc cognoscétis quia ego sum, et a meípso fácio nihil: sed, sicut dócuit me Pater, hæc loquor: et qui me misit, mecum est, et non relíquit me solum: quia ego, quæ plácita sunt ei, fácio semper."}],"Offertorium":[{"k":"ref","la":"Ps 15:7; 15:8"},{"k":"text","la":"Benedícam Dóminum, qui tríbuit mihi intelléctum: providébam Dóminum in conspéctu meo semper: quóniam a dextris est mihi, ne commóvear."}],"Secreta":[{"k":"text","la":"Hæc hóstia, Dómine, placatiónis et laudis, tua nos protectióne dignos effíciat."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 8:2"},{"k":"text","la":"Dómine, Dóminus noster, quam admirábile est nomen tuum in univérsa terra!"}],"Postcommunio":[{"k":"text","la":"Hæc nos commúnio, Dómine, purget a crímine: et cœléstis remédii fáciat esse consórtes."},{"k":"macro","name":"Per Dominum"}],"Super populum":[{"k":"rubric","la":"Oratio super populum"},{"k":"text","la":"Orémus."},{"k":"text","la":"Humiliáte cápita vestra Deo."},{"k":"text","la":"Adésto supplicatiónibus nostris, omnípotens Deus: et, quibus fidúciam sperándæ pietátis indúlges; consuétæ misericórdiæ tríbue benígnus efféctum."},{"k":"macro","name":"Per Dominum"}]},"hr":{"98c9327a730903c9":{"t":"Ps 25, 11-12, Ps 25, 1\n(Ps 25, 11-12) Spasi me, Gospodine, i smiluj mi se. Noge moje idu pravim putem. Pred mnoštvom naroda blagoslivljat ću Gospodina. (Ps 25, 1) Pogledaj, Gospodine, da li doista živim nevino. U Gospodina se uzdam, neću se pokolebati.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 25, 11-12) Spasi me, Gospodine, i smiluj mi se. Noge moje idu pravim putem. Pred mnoštvom naroda blagoslivljat ću Gospodina."},"82f59caf4a54fe7d":{"t":"<i>Pomolimo se</i>.\nPodaj, molimo, svemogući Bože, da se tvoja obitelj, koja se tjelesnom pokorom uzdržava od hrane, slijedeći pravednost uzdržava od grijeha.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj, molimo, svemogući Bože, da obitelj Tvoja trapećl se u tijelu i uskraćujući sebi jelo slijedi pravdu i uzdržava se od grijeha, po G. n.","knRef":"Kniewald 1942, str. 132–133 (snimka 67) (OCR)"},"ea589fae08564c76":{"t":"Dn 9, 15-19\nČitanje Daniela proroka. U one se dane pomoli Danijel: Gospodine Bože naš, koji si svoj narod snažnom rukom izveo iz egipatske zemlje i zaslužio ime koje imaš, sagriješili smo i učinili zlo protiv tvoje pravde. Odvrati, Gospodine, svoj gnjev i srdžbu od svoga grada Jeruzalema i svoje svete gore. Zbog naših grijeha i bezakonja naših otaca postao je Jeruzalem i tvoj narod ruglo svima našim susjedima. Usliši, Bože naš, molitve svojega sluge, čuj njegove prošnje, zbog samoga sebe pokaži se nad opustjelom svojom svetinjom. Prikloni svoje uho, Bože moj, i čuj. Otvori svoje oči i vidi naše rasulo i grad nad kojim je prizvano tvoje ime. K tebi upravljamo svoje molitve, ne pouzdavajući se u svoja pravedna djela, nego u tvoje veliko milosrđe. Usliši, Gospodine, ublaži se, Gospodine, pogledaj i ispuni obećanje. Bože moj, ne oklijevaj radi samog sebe, jer je tvoje ime prizvano nad tvojim gradom i tvojim narodom, Gospodine Bože naš!","kn":"Čitanje Danlela Proroka (Dan. 9, 15-19). U one dane: Daniel se pomoli Gospođinu govoreći: Gospodine Bože naš, koji si izveo puk svoj iz zemlje Egipatske rukom snažnom, i stekao sebi ime, kakvo ti je danas: sagriješismo, zlo učinismo. Gospodine, protiv svake pravde tvoje: neka se odvrati, p,roBim, gnjev tvoj i srdžba tvoja od grada Jeruzalema, i od svete gore tvoje. Jer zbog grijeha naših Jeruzalem i puk tvoj posta ruglo svima, koji su okolo nas. Sada dakle, usliši. Bože naš, molitvu sluge svojega, i molbe njegove: sebe samoga radi pokaži lice svoje nad svetinjom svojom, koja je opustjela. Prikloni, Bože moj, uho svoje, i čuj: otvori oči svoje, i vidi rasap naš, i grad, nad kojim je prizvano Ime tvoje; jer upravljamo molitve pred licem tvojim, ne zbog pravednosti svoje, nego zbog velikoga milosrđa tvojega. Usliši, Gospodine, utaži se. Gospodine: pogledaj i učini: ne oklijevaj sebe samoga radi. Bože moj: jer je. Ime tvoje prizvano nad gradom, i nad pukom tvojim. Gospodine, Bože naš.","knRef":"Kniewald 1942, str. 132–133 (snimka 67) (OCR)"},"c07d39856d7d7380":{"t":"Ps 69, 6 i 3\nBudi mi pomoćnik i osloboditelj. Gospodine, ne kasni. Neka se smetu i zastide neprijatelji moji koji mi rade o glavi.\n\nPs 102, 10, Ps 78, 8-9\n(Ps 102, 10) Gospodine, ne uzvrati nam prema našim grijesima koje smo učinili, niti prema našim krivicama. (Ps 78, 8-9) Gospodine, ne sjećaj se naših starih zloća, brzo neka nam dođe ususret tvoje milosrđe, jer postadosmo vrlo bijedni. [Ovdje se poklekne] Pomozi nam, Bože Spasitelju naš, i radi slave svojeg imena izbavi nas, Gospodine. Imaj samilosti s našim grijesima radi imena svojega.","kn":"(Ps. 69, 6, 3). Ti si pomoćnik moj i izbavitelj moj, Gospodine, ne kasni! Nek se smetu i postide, koji traže dušu moju!\n\n(Ps. 102, 10). Gospodine, ne postupaj s nama po grijesima našim i ne vraćaj nam po nepravdama našim. (Ps. 78, 8, 9) Gospodine, ne opominji se pređašnjih bezakonja naših, već neka nas brzo preteče milosrđe Tvoje, jer smo postali veoma ubogi (Ovdje se poklekne.) Pomozi nam. Bože, spasitelju naš, i radi slave imena svoga izbavi nas. Gospodine, i očisti nas od grijeha naših radi imena svoga.","knRef":"Kniewald 1942, str. 132–133 (snimka 67) (OCR)"},"18a2998d1c297247":{"t":"Iv 8, 21-29\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme reče Isus židovskom narodu: Ja idem, vi ćete me tražiti i umrijet ćete u svojem grijehu. Kamo ja idem, vi ne možete doći. Židovi se stanu pitati: Zar će sam sebe ubiti, kad kaže: Kamo ja idem, vi ne možete doći? I nastavi Isus: Vi ste sa zemlje, a ja sam s neba. Vi ste s ovog svijeta, a ja nisam s ovog svijeta. Rekao sam vam da ćete umrijeti u svojim grijesima. Ako ne budete vjerovali, da ja jesam, umrijet ćete u svojim grijesima. Tko si ti? upitaju ga. Isus odgovori: Početak, koji vam i govorim. Imao bih mnogo govoriti o vama i suditi. Istinit je onaj koji me poslao. Govorim svijetu što sam čuo od njega. Nisu razumjeli, da govori o Bogu svojem Ocu. Tada im reče Isus: Kada podignete Sina Čovječjega, onda ćete se uvjeriti da ne činim ništa od sebe, nego da govorim što me naučio Otac. Sa mnom je onaj koji me posla i ne ostavlja me samoga, jer ja uvijek činim što je njemu drago.","kn":"t Slijedi sv. evanđelje po Ivanu (8, 21-29). U ono vrijeme reče Isus mnoštvu židovskomu: Ja idem i tražit ćete me i umrijet ćete u svojem grijehu. Kamo ja idem, vi ne možete doći. Tada rekoše Židovi: Ne ćeš li sam sebe ubiti, kad govoriš: Kamo ja idem vi ne možete doći? I reče im: vi ste odozdo, a ja sam odozgo, vi ste od ovoga svijeta. A ja sam vam rekao, da ćete umrijeti u svojim grij^ima, jer ako ne uzvjerujete, da sam ja, umrijet ćete ^u svojim grijesima. Tada mu rekoše: tko si? Reče im Isus: Svakako to, što vam odavno govorim. Mnogo imam govoriti i suditi o vama, ali onaj, koji me je poslao, istinit je i ja. ono govorim^ u svijetu, što sam čuo od njega. I ne opaziše, da im je govorio o svojem Ocu. Onda im reče Isus: kad podignete Sina čovječjega, onda ćete upoznati da sam ja, i da ništa sam od sebe ne činim, kako me je Otac naiučiO', onako govorim. I onaj, koji me je poslao, sa mnom je, i nije me ostavio sama, jer ja uvijek činim ono, što je -njemu ugodno.","knRef":"Kniewald 1942, str. 132–133 (snimka 67) (OCR)"},"3f6e5a17935a2cc5":{"t":"Ps 15, 7 i 8\nBlagoslivljam Gospodina što mi je dao razum. Uvijek imam Boga pred očima. On mi je s desne strane, neću se pokolebati.","v":"deum → dominum","kn":"(Ps. 15, 7, 8). Blagosivam Gospodina, koji mi je dao razum; svagda imam^ pred sobom Gospodina, on mi je s desne strane, da ne posrnem.","knRef":"Kniewald 1942, str. 132–133 (snimka 67) (OCR)"},"1a855b2b71eb277b":{"t":"Neka nas, Gospodine, ovaj prinos pomirenja i hvale učini dostojnima tvoje zaštite.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Ova žrtva pomirenja i hvale. Gospodine, učinila nas vrijednima Tvoje zaštite, po G. n.","knRef":"Kniewald 1942, str. 132–133 (snimka 67) (OCR)"},"8e0447f4695d07e4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi Gospodine, sveti Oče, svemogući vječni Bože: – ti tjelesnim postom suzbijaš opačine, uzdižeš dušu, daješ krepost i nagrade po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo 1 spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože. koji tjelesnim postom obuzdavaš opačine, duh dižeš, daješ krepost i nagrade,' po Kristu, Gospodinu našemu; po kojem veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti, Nebesa Te 1 nebeske Red i čin sv. mise moći i blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se s njima smiju sjediniti i naši glasovi, koji govore u smjernom ispovijedanju:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"e7ae5f2057fe9291":{"t":"Ps 8, 2\nGospodine, Gospodine naš, kako je divno ime tvoje po svoj zemlji.","kn":"(Ps. 3, 2). Gospodine, Gospodine naš, kako je divno ime Tvoje po svoj zemlji!","knRef":"Kniewald 1942, str. 134–135 (snimka 68) (OCR)"},"1e3d1e0935acb744":{"t":"<i>Pomolimo se</i>.\nOčistila nas, Gospodine, ova pričest od opačina i učinila nas dionicima nebeske okrepe.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Ova :ims Pričest, Gospodine, očistila od krivnje i učinila dionicima nebeske okrepe, PO G. n.","knRef":"Kniewald 1942, str. 134–135 (snimka 68) (OCR)"},"9f09c7c7fc598228":{"t":"<i>Pomolimo se</i>.\n<i>Prignite pred Bogom svoje glave</i>.\nMilostiv budi, svemogući Bože, našim vapajima i dobrostivo udijeli učinak običajnog milosrđa nama kojima daješ pouzdanje u očinsku dobrotu kojoj se nadamo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Pomolimo se! Prignite ponizno glave svoje pred Bogom! Primi molitve naše, svemogući Bože, i podaj blagostivo učinak svog običajnog milosrđa onima, kojima darivaš pouzdanje u Tvoju dobrostivost, po G. n.","knRef":"Kniewald 1942, str. 134–135 (snimka 68) (OCR)"}}});
